const jobs = $input.all()
  .filter(i => i.json.title && String(i.json.title).trim() !== '')
  .filter(i => !i.json.ai_analyzed)
  .slice(0, 10);

const SYSTEM = `You score job postings for one candidate. Reply with JSON only.

Candidate: junior-level, based in Karachi, Pakistan. Wants DevOps, SRE, cloud (AWS/Azure/GCP), Kubernetes/Docker, Linux, system administration, infrastructure/platform engineering, network engineering, IT support / technical support.
Can work: on-site or hybrid in Karachi, or remote roles open to Pakistan.

Rules:
- Use ONLY information in the posting. If the description is empty, judge from title, company and location, and say so in ai_reason.
- Never invent skills or requirements. Use empty arrays if nothing is stated.
- If the location is outside Pakistan and the job is not remote, subtract 20 from the score.
- job_category must be one of: devops_cloud, linux_infra, network, it_support, software_dev, other.
- seniority must be one of: intern, junior, mid, senior, unknown.
- ai_recommendation must be one of: apply, maybe, skip.
- required_skills and nice_to_have_skills: at most 8 items each, no duplicates.

JSON shape:
{"relevance_score": 0, "job_category": "", "seniority": "", "required_skills": [], "nice_to_have_skills": [], "ai_recommendation": "", "ai_reason": ""}`;

return jobs.map(i => {
  const j = i.json;
  const posting = [
    'Title: ' + (j.title || ''),
    'Company: ' + (j.company || ''),
    'Location: ' + (j.location || ''),
    'Remote: ' + (j.is_remote ? 'yes' : 'no'),
    'Salary: ' + (j.salary || 'not stated'),
    'Description: ' + String(j.description || '(none provided)').slice(0, 2000)
  ].join('\n');

  return { json: {
    row_id: j.id,
    title: j.title,
    request: {
      model: 'qwen2.5:3b',
      stream: false,
      format: 'json',
      keep_alive: '30m',
      options: { temperature: 0.1, num_ctx: 4096, num_predict: 600 },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: posting }
      ]
    }
  }};
});

const ALLOWED_CAT = ['devops_cloud','linux_infra','network','it_support','software_dev','wordpress','other'];
const ALLOWED_SEN = ['intern','junior','mid','senior','unknown'];
const prompts = $('Build Prompt').all();
const jobs = $('Get Jobs').all();
const arr = v => Array.isArray(v) ? v.map(String).slice(0, 8).join(', ') : '';

function classify(title) {
  const t = (title || '').toLowerCase();
  if (/devops|site reliability|\bsre\b|cloud|kubernetes|platform engineer|mlops/.test(t)) return 'devops_cloud';
  if (/linux|system(s)? (admin|engineer)|sysadmin|infrastructure/.test(t)) return 'linux_infra';
  if (/network/.test(t)) return 'network';
  if (/it support|technical support|help ?desk|support engineer/.test(t)) return 'it_support';
  if (/developer|software|engineer|full.?stack|back.?end|front.?end|qa/.test(t)) return 'software_dev';
  if (/wordpress|\bwp\b|elementor|woocommerce/.test(t)) return 'wordpress';

  return null;
}

function titleSeniority(title) {
  const t = (title || '').toLowerCase();
  if (/senior|\bsr\b|lead|principal|staff|head of/.test(t)) return 'senior';
  if (/intern|trainee|graduate/.test(t)) return 'intern';
  if (/junior|\bjr\b|entry/.test(t)) return 'junior';
  return null;
}

function analyze(j) {
  const text = [j.title, j.description, j.location].join(' ');
  const flags = [];

  if (/work authori[sz]ation|visa sponsorship|(must|need to) be (a )?(u\.?s\.?|us) (citizen|resident)|security clearance|clearance required/i.test(text)) {
    flags.push('work authorization or clearance mentioned');
  }

  if (/night shift|graveyard/i.test(text)) {
    flags.push('night shift');
  }

  const yrs = [...text.matchAll(/(\d+)\s*\+?\s*years/gi)].map(m => Number(m[1])).filter(n => n < 30);
  const maxYrs = yrs.length ? Math.max(...yrs) : 0;
  if (maxYrs >= 3) flags.push(maxYrs + '+ years experience mentioned');

  const city = j.location || '';
  const inKarachi = /karachi/i.test(city);
  const inPakistan = inKarachi || /pakistan|lahore|islamabad|rawalpindi|faisalabad|multan|peshawar|quetta|sialkot|gujranwala/i.test(city);

  // FIXED LOCATION CHECK:
  if (!j.is_remote && !inPakistan) {
    flags.push('on-site outside Pakistan');
  } else if (!j.is_remote && !inKarachi) {
    flags.push('on-site in another Pakistani city');
  }

  return { flags, maxYrs };
}

const BASE = { devops_cloud: 85, linux_infra: 72, network: 68, it_support: 52, wordpress: 60, software_dev: 28, other: 8 };

const out = [];
$input.all().forEach((item, idx) => {
  const row_id = prompts[idx].json.row_id;
  let r;
  try { r = JSON.parse(item.json.message.content); } catch (e) { return; }
  const job = (jobs.find(x => x.json.id == row_id) || { json: {} }).json;

  const cat = classify(job.title) || (ALLOWED_CAT.includes(r.job_category) ? r.job_category : 'other');
  const seniority = titleSeniority(job.title) || (ALLOWED_SEN.includes(r.seniority) ? r.seniority : 'unknown');
  const { flags, maxYrs } = analyze(job);
  const IT_TERMS = /\b(computer|network|networking|windows|linux|hardware|software|desktop|laptop|printer|helpdesk|help desk|troubleshoot\w*|server|cloud|aws|azure|ticket\w*|it support|technology|infrastructure|devops|active directory|vpn|lan|wan)\b/i;
  const descLen = String(job.description || '').trim().length;
  if (cat === 'it_support' && descLen >= 60 && !IT_TERMS.test(job.description)) flags.push('posting text has no IT terms');

  let score = BASE[cat];
  if (seniority === 'senior') score -= 35;
  if (/staff|principal|head of/i.test(job.title || '')) score -= 15;
  if (maxYrs >= 5) score -= 15; else if (maxYrs >= 3) score -= 5;
  if (flags.some(f => f.startsWith('on-site outside'))) score -= 20;
  if (flags.some(f => f.startsWith('work authorization'))) score -= 20;
  if (flags.includes('posting text has no IT terms')) score -= 30;
  score = Math.max(0, Math.min(100, score));
  let rec = score >= 65 ? 'apply' : score >= 40 ? 'maybe' : 'skip';
  if (maxYrs >= 5 && rec === 'apply') rec = 'maybe';
  if (flags.includes('on-site in another Pakistani city')) score -= 25;
  out.push({ json: {
    row_id,
    ai_analyzed: true,
    relevance_score: score,
    job_category: cat,
    seniority,
    required_skills: arr(r.required_skills),
    nice_to_have_skills: arr(r.nice_to_have_skills),
    red_flags: flags.join(', '),
    ai_recommendation: rec,
    ai_reason: ('Category ' + cat + ', seniority ' + seniority + '. Model note: ' + String(r.ai_reason || '')).slice(0, 300)
  }});
});
return out;
